					<?php
					// Получаем все категории товаров WooCommerce
					$product_categories = get_terms(array(
						'taxonomy' => 'product_cat',
						'hide_empty' => false, // показывать только категории с товарами
						'orderby' => 'menu_order',
						'order' => 'ASC'
					));

					if (!empty($product_categories) && !is_wp_error($product_categories)):
						foreach ($product_categories as $category):
							if ($category->slug == 'misc') {
								continue;
							}
							// Ссылка на категорию
							$category_link = get_term_link($category);
							// Количество товаров в категории
							$product_count = $category->count;
							?>
							<li class="catalog-menu__item">
								<a class="catalog-menu__link" href="<?php echo esc_url($category_link); ?>">
									<span class="catalog-menu__text">
										<?php echo esc_html($category->name); ?>
									</span>
									<span class="catalog-menu__quantity">
										<?php echo esc_html($product_count); ?> товаров
									</span>
								</a>
							</li>
							<?php
						endforeach;
					endif;
					?>
				</ul>

